import DataCard from '@github-ui/data-card'
import {number as formatNumber} from '@github-ui/formatters'
import {Link} from '@primer/react'

import {usePaths} from '../../../common/contexts/Paths'
import {sanitizeDependabotQuery} from '../../../common/utils/query-helper'
import styles from './MostVulnerablePackageCard.module.css'
import useMostVulnQuery, {type UseMostVulnQueryParams} from './use-most-vuln-query'

interface MostVulnerablePackageCardProps extends UseMostVulnQueryParams {
  allowedDependabotQualifiers?: string[]
}

export default function MostVulnerablePackageCard(props: MostVulnerablePackageCardProps): React.ReactElement {
  const dataQuery = useMostVulnQuery(props)
  const paths = usePaths()
  const query = props.query
  const allowedDependabotQualifiers = props.allowedDependabotQualifiers || []

  let actionUrl = undefined
  let alertCount = 0

  if (dataQuery.isSuccess) {
    // Safely cast dataQuery.data to a known type
    const sanitizeBaseQuery = sanitizeDependabotQuery(query, allowedDependabotQualifiers)
    const searchQuery = [sanitizeBaseQuery, `package:${dataQuery.data.packageName}`].filter(Boolean).join(' ')
    actionUrl = paths.dependabotAlertsListPath({query: searchQuery.trim()})
    alertCount = dataQuery.data.alertCount
  }

  return (
    <DataCard
      cardTitle="Most vulnerabilities"
      action={
        actionUrl && (
          <Link className="f6 no-wrap" href={actionUrl} data-testid="data-card-action-link">
            View all {formatNumber(alertCount)} alerts
          </Link>
        )
      }
      loading={dataQuery.isPending}
      error={dataQuery.isError}
    >
      {dataQuery.isSuccess &&
        ((): React.ReactElement => {
          // Explicitly cast dataQuery.data in the render block
          const safeData = dataQuery.data as {packageName: string; alertCount: number}
          return (
            <>
              {/* Package name with most vulnerabilities */}
              <h2 className={styles.mostVulnerableText}>{safeData.packageName}</h2>
            </>
          )
        })()}
    </DataCard>
  )
}
