import type {UseQueryResult} from '@github-ui/react-query'

import {usePaths} from '../../../common/contexts/Paths'
import {useQuery} from '../../../common/hooks/use-config-query'
import {fetchJson} from '../../../common/utils/fetch-json'

interface AlertsFixedWithAutofixResult {
  accepted: number
  suggested: number
}

export interface UseAlertsFixedWithAutofixAllBranchesQueryParams {
  query: string
  startDate: string
  endDate: string
}
export default function useAlertsFixedWithAutofixAllBranchesQuery({
  query,
  startDate,
  endDate,
}: UseAlertsFixedWithAutofixAllBranchesQueryParams): UseQueryResult<AlertsFixedWithAutofixResult> {
  const paths = usePaths()
  const path = paths.codeScanningAlertsFixedWithAutofixAllBranchesPath({
    query,
    startDate,
    endDate,
  })

  return useQuery({
    queryKey: [path],
    queryFn: () => fetchJson(path),
  })
}
