import DataCard from '@github-ui/data-card'
import {useMemo} from 'react'

import useAlertsFixedWithAutofixAllBranchesQuery, {
  type UseAlertsFixedWithAutofixAllBranchesQueryParams,
} from './use-alerts-fixed-with-autofix-all-branches-query'

interface AlertsFixedWithAutofixAllBranchesCardProps extends UseAlertsFixedWithAutofixAllBranchesQueryParams {}

export default function AlertsFixedWithAutofixAllBranchesCard(
  props: AlertsFixedWithAutofixAllBranchesCardProps,
): React.ReactElement {
  const dataQuery = useAlertsFixedWithAutofixAllBranchesQuery(props)

  const [percentageAccepted, percentageNotAccepted] = useMemo(() => {
    if (!dataQuery.isSuccess) return [0, 100]
    if (dataQuery.data.suggested === 0) return [0, 100]

    const accepted = (100 * dataQuery.data.accepted) / dataQuery.data.suggested
    return [accepted, 100 - accepted]
  }, [dataQuery])

  return (
    <DataCard
      cardTitle="Alerts fixed with autofix suggestions on all branches"
      loading={dataQuery.isPending}
      error={dataQuery.isError}
    >
      {dataQuery.isSuccess && (
        <>
          <DataCard.Counter count={dataQuery.data.accepted} total={dataQuery.data.suggested} />
          <DataCard.ProgressBar
            aria-label={`${percentageAccepted.toFixed(2)}% of autofix suggestions were accepted`}
            data={[
              {
                progress: percentageAccepted,
                color: 'var(--bgColor-success-emphasis)',
                label: `${percentageAccepted.toFixed(2)}% of autofix suggestions were accepted`,
              },
              {
                progress: percentageNotAccepted,
                color: 'var(--bgColor-accent-emphasis)',
                label: `${percentageNotAccepted.toFixed(2)}% of autofix suggestions were not accepted`,
              },
            ]}
          />
          <DataCard.Description>
            Total alerts (in all branches) fixed with an accepted autofix out of all with a suggested autofix
          </DataCard.Description>
        </>
      )}
    </DataCard>
  )
}
