import type {UseQueryResult} from '@github-ui/react-query'

import {usePaths} from '../../../common/contexts/Paths'
import {useQuery} from '../../../common/hooks/use-config-query'
import {fetchJson} from '../../../common/utils/fetch-json'

interface AlertsClosedByStateResult {
  dismissed: number
  fixed: number
  autoDismissed: number
  percentageChangeInTotalClosedAlertsPast30Days: number
}

export interface UseAlertsClosedByStateQueryParams {
  query: string
}
export default function useAlertsClosedByStateQuery({
  query,
}: UseAlertsClosedByStateQueryParams): UseQueryResult<AlertsClosedByStateResult> {
  const paths = usePaths()
  const path = paths.dependabotAlertsClosedByStatePath({
    query,
  })

  return useQuery({
    queryKey: [path],
    queryFn: () => fetchJson(path),
  })
}
