import type {UseQueryResult} from '@github-ui/react-query'

import {usePaths} from '../../../common/contexts/Paths'
import {useQuery} from '../../../common/hooks/use-config-query'
import {fetchJson} from '../../../common/utils/fetch-json'

interface MostVulnerableResult {
  packageName: string
  alertCount: number
}

export interface UseMostVulnQueryParams {
  query: string
}

export default function useMostVulnQuery({query}: UseMostVulnQueryParams): UseQueryResult<MostVulnerableResult> {
  const paths = usePaths()
  const path = paths.dependabotMostVulnerablePath({
    query,
  })

  return useQuery({
    queryKey: [path],
    queryFn: () => fetchJson(path),
  })
}
