import DataCard from '@github-ui/data-card'
import {number as formatNumber} from '@github-ui/formatters'
import {ArrowDownIcon, ArrowUpIcon, DotFillIcon} from '@primer/octicons-react'

import rawStyles from './AlertsClosedByStateCard.module.css'
import useAlertsClosedByStateQuery, {type UseAlertsClosedByStateQueryParams} from './use-alerts-closed-by-state-query'

const styles = rawStyles as Record<string, string>

interface AlertsClosedByStateCardProps extends UseAlertsClosedByStateQueryParams {}

export default function AlertsClosedByStateCard(props: AlertsClosedByStateCardProps): React.ReactElement {
  const dataQuery = useAlertsClosedByStateQuery(props)

  return (
    <DataCard
      cardTitle="Alerts closed in the last 30 days"
      loading={dataQuery.isPending}
      error={dataQuery.isError}
      /* Percentage increase indicator */
      action={
        dataQuery.isSuccess &&
        ((): React.ReactElement => {
          const percentageChange = dataQuery.data.percentageChangeInTotalClosedAlertsPast30Days
          return (
            <div className={percentageChange >= 0 ? 'color-fg-success' : 'color-fg-danger'}>
              {((): React.ReactElement => {
                const IconComponent = percentageChange >= 0 ? ArrowUpIcon : ArrowDownIcon
                return (
                  <IconComponent
                    size={12}
                    className="mr-1 v-align-text-bottom"
                    aria-label={percentageChange >= 0 ? 'Increased' : 'Decreased'}
                  />
                )
              })()}
              <span className={styles.percentageChangeText}>{formatNumber(percentageChange, {precision: 0})}%</span>
            </div>
          )
        })()
      }
    >
      {dataQuery.isSuccess &&
        ((): React.ReactElement => {
          // Explicitly cast dataQuery.data in the render block
          const {dismissed, fixed, autoDismissed} = dataQuery.data as {
            dismissed: number
            fixed: number
            autoDismissed: number
          }
          const total = dismissed + fixed + autoDismissed

          const totalDescription = `${formatNumber(total)} alerts`
          const fixedDescription = `${formatNumber(fixed)} fixed with Dependabot`
          const dismissedDescription = `${formatNumber(dismissed)} manually dismissed`
          const autoDismissedDescription = `${formatNumber(autoDismissed)} auto-dismissed`
          const fixedColor = 'var(--data-blue-color-emphasis)'
          const dismissedColor = 'var(--data-green-color-emphasis)'
          const autoDismissedColor = 'var(--data-orange-color-emphasis)'

          return (
            <>
              {/* Total alerts count */}
              <h2 className={styles.totalAlertsText}>{totalDescription}</h2>

              {/* Progress bar */}
              <DataCard.ProgressBar
                aria-label={`${fixedDescription}, ${dismissedDescription}, ${autoDismissedDescription}`}
                data={[
                  {
                    progress: calculatePercentage(total, fixed),
                    color: fixedColor,
                    label: fixedDescription,
                  },
                  {
                    progress: calculatePercentage(total, dismissed),
                    color: dismissedColor,
                    label: dismissedDescription,
                  },
                  {
                    progress: calculatePercentage(total, autoDismissed),
                    color: autoDismissedColor,
                    label: autoDismissedDescription,
                  },
                ]}
              />

              {/* Progress bar legend */}
              <div className="d-flex flex-wrap pb-2 mt-2">
                <LegendItem dotColorClass={fixedColor} label={fixedDescription} />
                <LegendItem dotColorClass={dismissedColor} label={dismissedDescription} />
                <LegendItem dotColorClass={autoDismissedColor} label={autoDismissedDescription} />
              </div>
            </>
          )
        })()}
    </DataCard>
  )
}

const LegendItem = ({dotColorClass, label}: {dotColorClass: string; label: string}): React.ReactElement => {
  return (
    <span className="mr-2">
      <span style={{color: dotColorClass}}>
        <DotFillIcon />
      </span>
      <span className={'color-fg-muted f6'}>{label}</span>
    </span>
  )
}

const calculatePercentage = (total: number, count: number): number => {
  return total === 0 ? 0 : (count / total) * 100 // Protect against division by zero
}
